using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogs) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogs)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [FormerlySerializedAs("debugLogs")]
    [SerializeField] private bool debugLogsDirectional = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogsDirectional) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogsDirectional)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using BridgeItTogether.Gameplay.Abstractions;
using BridgeItTogether.Gameplay.SafeZones;

namespace BridgeItTogether.Gameplay.AutoControllers
{
    [DisallowMultipleComponent]
    public class AutoController : MonoBehaviour
    {
        // ==== Movimiento ====
        [Header("Movimiento")]
        [SerializeField] private float velocidadBase = 5f;
        public Vector3 direccionInicial = Vector3.right;

        // ==== Tags (informativos) ====
        [Header("Tags")]
        [SerializeField] private bool asegurarTagVehiculo = true;
        [SerializeField] private string nombreTagVehiculo = "Vehicle";

        // ==== Lanzamiento de IHitable (Parábola Física) ====
        [Header("Lanzamiento IHitable (Parábola Física)")]
        [SerializeField] private string safeZoneTag = "SafeZone";
        [SerializeField, Range(10f, 80f)] private float launchAngleDeg = 45f;
        [SerializeField, Min(0.1f)] private float launchSpeed = 12f;
        [SerializeField, Min(0.1f)] private float launchGravity = 9.81f;
        [SerializeField] private bool kinematicDuringLaunch = true;
        [SerializeField] private float minLaunchDistance = 0.05f;
        [SerializeField] private float ignoreCollisionDuration = 0.5f; // Tiempo para re-habilitar colisiones después del impacto con IHitable

        // Estado
        private Rigidbody rb;
        private bool isInitialized;
        private bool isPaused;
        private Vector3 direccionMovimiento;
        private readonly Dictionary<Transform, Coroutine> activeLaunches = new();
        private readonly HashSet<Collider> currentlyIgnoredColliders = new HashSet<Collider>();

        private void Awake()
        {
            direccionMovimiento = direccionInicial.sqrMagnitude > 0.0001f ? direccionInicial.normalized : Vector3.right;
        }

        public void Initialize(Vector3 direction)
        {
            SetDirection(direction);

            if (asegurarTagVehiculo)
            {
                try
                {
                    if (!string.IsNullOrEmpty(nombreTagVehiculo) && !CompareTag(nombreTagVehiculo))
                        tag = nombreTagVehiculo;
                }
                catch (UnityException)
                {
                    Debug.LogWarning($"[AutoController] Tag '{nombreTagVehiculo}' no existe. Agrega el Tag en Project Settings.", this);
                }
            }

            rb = GetComponent<Rigidbody>() ?? gameObject.AddComponent<Rigidbody>();
#if UNITY_6000_0_OR_NEWER
            rb.linearVelocity = Vector3.zero;
#else
            rb.velocity = Vector3.zero;
#endif
            rb.angularVelocity = Vector3.zero;

            AlinearRotacionConDireccion();
            isInitialized = true;
            isPaused = false;
        }

        protected virtual void FixedUpdate()
        {
            if (!isInitialized || isPaused) return;

            if (rb != null && velocidadBase > 0f)
            {
                Vector3 dir = direccionMovimiento.sqrMagnitude > 0.0001f ? direccionMovimiento.normalized : Vector3.right;
                rb.MovePosition(rb.position + dir * velocidadBase * Time.fixedDeltaTime);
            }
        }

        public void SetSpeed(float speed) => velocidadBase = Mathf.Max(0f, speed);
        public float GetSpeed() => velocidadBase;

        public void SetDirection(Vector3 direction)
        {
            if (direction.sqrMagnitude > 0.0001f)
                direccionMovimiento = direction.normalized;
            AlinearRotacionConDireccion();
        }

        public void Pause()
        {
            isPaused = true;
            if (rb != null)
            {
#if UNITY_6000_0_OR_NEWER
                rb.linearVelocity = new Vector3(0f, rb.linearVelocity.y, 0f);
#else
                rb.velocity = new Vector3(0f, rb.velocity.y, 0f);
#endif
                rb.angularVelocity = Vector3.zero;
            }
        }

        public void Resume()
        {
            isPaused = false;
            AlinearRotacionConDireccion();
        }

        private void AlinearRotacionConDireccion()
        {
            Vector3 look = new Vector3(direccionMovimiento.x, 0f, direccionMovimiento.z);
            if (look.sqrMagnitude > 0.0001f)
                transform.rotation = Quaternion.LookRotation(look, Vector3.up);
        }

        // ===================== IHitable: colisión y lanzamiento =====================
        private void OnCollisionEnter(Collision collision)
        {
            if (!isInitialized) return;

            // Solo procesar colisiones con objetos IHitable (players, etc.)
            var hitable = collision.collider.GetComponentInParent<IHitable>();
            if (hitable == null)
            {
                // No es IHitable: dejar que la física actúe normalmente (suelo, puente, etc.)
                // Solo procesar cuadrantes si aplica
                TryHandleQuadrantCollision(collision.collider);
                return;
            }

            // Es IHitable: ignorar colisiones temporalmente para evitar bugs de colisión repetida
            StartCoroutine(TemporarilyIgnoreCollision(collision.collider));

            // Resto de comportamiento normal para IHitable
            if (TryHandleQuadrantCollision(collision.collider)) return;
            TryLaunchHitable(collision.collider);
        }

        private void OnTriggerEnter(Collider other)
        {
            if (!isInitialized) return;

            if (TryHandleQuadrantCollision(other)) return;
            TryLaunchHitable(other);
        }

        // csharp
        private bool TryHandleQuadrantCollision(Collider col)
        {
            if (col == null) return false;

            var quadrantInst = col.GetComponentInParent<BridgeQuadrantInstance>();
            if (quadrantInst != null && quadrantInst.quadrantSO != null)
            {
                var so = quadrantInst.quadrantSO;
                var layers = so.requiredLayers;

                bool shouldDestroy = false;

                if (layers != null && layers.Length >= 1)
                {
                    bool layer0Done = layers[0].isCompleted;
                    // consider layer2 as the "top" layer; if it doesn't exist treat as not completed
                    bool layer2Done = (layers.Length > 2) ? layers[2].isCompleted : false;

                    // Destroy when base (layer0) is present and the top layer is NOT present.
                    // This covers both: layer1 missing (layer0 built) and layer1 present but layer2 missing.
                    shouldDestroy = layer0Done && !layer2Done;
                }
                else
                {
                    // Fallback: require first layer completed and last layer not completed
                    if (layers != null && layers.Length > 0)
                    {
                        bool firstDone = layers[0].isCompleted;
                        bool lastDone = layers[layers.Length - 1].isCompleted;
                        shouldDestroy = firstDone && !lastDone;
                    }
                }

                if (shouldDestroy)
                {
                    so.ForceDestroyQuadrant();
                    Debug.Log($"[AutoController] Forced destroy quadrant on '{quadrantInst.name}' due to vehicle collision.");
                    return true;
                }

                // If conditions not met (e.g. top layer already completed), do not destroy and allow normal pass-through
                return false;
            }

            return false;
        }


        private void TryLaunchHitable(Collider col)
        {
            if (col == null) return;

            var hitable = col.GetComponent<IHitable>();
            if (hitable == null) return;

            var targetT = (hitable as Component)?.transform;
            if (targetT == null) return;

            if (IsObjectBeingHeld(targetT))
            {
                var holder = FindPlayerHoldingObject(targetT);
                if (holder != null)
                {
                    TryLaunchHitable(holder.GetComponent<Collider>());
                }
                return;
            }

            if (targetT != transform && targetT.IsChildOf(transform))
                targetT.SetParent(null, true);

            if (activeLaunches.ContainsKey(targetT)) return;

            if (!TryGetRandomPointInNearestSafeZone(targetT.position, out var destino)) return;

            hitable.OnLaunched(destino);

            var routine = StartCoroutine(LaunchRoutine(targetT, destino));
            activeLaunches[targetT] = routine;
        }

        private bool IsObjectBeingHeld(Transform obj)
        {
            var holders = FindObjectsOfType<PlayerObjectHolder>();
            foreach (var holder in holders)
            {
                if (holder.HasObjectInHand() && holder.GetHeldObject() == obj.gameObject)
                    return true;
            }
            return false;
        }

        private PlayerObjectHolder FindPlayerHoldingObject(Transform obj)
        {
            var holders = FindObjectsOfType<PlayerObjectHolder>();
            foreach (var holder in holders)
            {
                if (holder.HasObjectInHand() && holder.GetHeldObject() == obj.gameObject)
                    return holder;
            }
            return null;
        }

        private IEnumerator LaunchRoutine(Transform target, Vector3 destino)
        {
            if (target == null) yield break;
            if (target.IsChildOf(transform))
                target.SetParent(null, true);

            Vector3 start = target.position;
            Vector3 end = destino;

            // Calcular distancia horizontal y diferencia de altura
            Vector3 horizontalDisplacement = new Vector3(end.x - start.x, 0f, end.z - start.z);
            float horizontalDistance = horizontalDisplacement.magnitude;

            if (horizontalDistance < minLaunchDistance)
            {
                activeLaunches.Remove(target);
                yield break;
            }

            Vector3 horizontalDir = horizontalDisplacement / horizontalDistance;
            float heightDifference = end.y - start.y;

            // Calcular velocidad inicial necesaria para llegar EXACTAMENTE al destino
            // Fórmula balística: v = sqrt(g * d^2 / (2 * cos^2(θ) * (d * tan(θ) - h)))
            float g = Mathf.Max(0.01f, launchGravity);
            float angleRad = launchAngleDeg * Mathf.Deg2Rad;
            float tanAngle = Mathf.Tan(angleRad);
            float cosAngle = Mathf.Cos(angleRad);

            float denominator = 2f * cosAngle * cosAngle * (horizontalDistance * tanAngle - heightDifference);

            if (denominator <= 0f)
            {
                // No hay solución física con este ángulo, usar velocidad fija como fallback
                Debug.LogWarning($"[AutoController] No se puede calcular trayectoria exacta con ángulo {launchAngleDeg}°. Usando fallback.");
                activeLaunches.Remove(target);
                yield break;
            }

            float velocitySquared = (g * horizontalDistance * horizontalDistance) / denominator;
            float velocity = Mathf.Sqrt(velocitySquared);

            // Calcular tiempo de vuelo
            float totalTime = horizontalDistance / (velocity * cosAngle);

            // Detectar si tiene CharacterController (Players) o Rigidbody (Materiales, objetos)
            CharacterController charController = target.GetComponent<CharacterController>();
            Rigidbody trb = target.GetComponent<Rigidbody>();

            bool hasCharController = charController != null;
            bool hasRigidbody = trb != null;

            bool prevCharControllerEnabled = false;
            bool prevRigidbodyKinematic = false;

            // Deshabilitar CharacterController durante lanzamiento (Players)
            if (hasCharController)
            {
                prevCharControllerEnabled = charController.enabled;
                charController.enabled = false;
            }

            // Hacer kinematic el Rigidbody durante lanzamiento (Materiales/objetos con física)
            if (hasRigidbody && kinematicDuringLaunch)
            {
                prevRigidbodyKinematic = trb.isKinematic;
#if UNITY_6000_0_OR_NEWER
                trb.linearVelocity = Vector3.zero;
#else
                trb.velocity = Vector3.zero;
#endif
                trb.angularVelocity = Vector3.zero;
                trb.isKinematic = true;
            }

            // Ejecutar parábola balística exacta
            float t = 0f;

            while (t < totalTime && target != null)
            {
                t += Time.deltaTime;
                float ct = Mathf.Clamp(t, 0f, totalTime);

                // Posición horizontal (movimiento uniforme)
                float horizontalProgress = velocity * cosAngle * ct;

                // Posición vertical (movimiento parabólico)
                float verticalProgress = velocity * Mathf.Sin(angleRad) * ct - 0.5f * g * ct * ct;

                Vector3 newPosition = start + horizontalDir * horizontalProgress;
                newPosition.y = start.y + verticalProgress;

                target.position = newPosition;

                yield return null;
            }

            // Colocar EXACTAMENTE en el destino al finalizar
            if (target != null)
            {
                target.position = destino;
            }

            // Restaurar CharacterController
            if (hasCharController && charController != null)
            {
                charController.enabled = prevCharControllerEnabled;
            }

            // Restaurar Rigidbody
            if (hasRigidbody && kinematicDuringLaunch && trb != null)
            {
                trb.isKinematic = prevRigidbodyKinematic;
            }


            if (target != null)
                activeLaunches.Remove(target);
        }

        private bool TryGetRandomPointInNearestSafeZone(Vector3 from, out Vector3 point)
        {
            point = default;
            GameObject[] zones = GameObject.FindGameObjectsWithTag(safeZoneTag);
            if (zones == null || zones.Length == 0) return false;

            SafeZoneArea bestArea = null;
            Transform fallback = null;
            float bestDist = float.MaxValue;

            for (int i = 0; i < zones.Length; i++)
            {
                var go = zones[i];
                if (go == null) continue;

                var area = go.GetComponent<SafeZoneArea>();
                var t = go.transform;
                float d = (t.position - from).sqrMagnitude;

                if (area != null)
                {
                    if (d < bestDist)
                    {
                        bestDist = d;
                        bestArea = area;
                        fallback = t;
                    }
                }
                else
                {
                    if (d < bestDist)
                    {
                        bestDist = d;
                        fallback = t;
                    }
                }
            }

            if (bestArea != null)
            {
                point = bestArea.GetRandomPointInside();
                return true;
            }

            if (fallback != null)
            {
                point = fallback.position;
                return true;
            }

            return false;
        }

        /// <summary>
        /// Ignora temporalmente las colisiones con el collider especificado (solo IHitable) y luego las restaura.
        /// Esto evita bugs de colisión repetida mientras permite que el auto vuelva a chocar más adelante.
        /// </summary>
        private IEnumerator TemporarilyIgnoreCollision(Collider otherCollider)
        {
            if (otherCollider == null) yield break;

            var myCollider = GetComponent<Collider>();
            if (myCollider == null) yield break;

            // Si ya estamos ignorando este collider, no duplicar la coroutine
            if (currentlyIgnoredColliders.Contains(otherCollider)) yield break;

            // Ignorar colisiones
            Physics.IgnoreCollision(otherCollider, myCollider, true);
            currentlyIgnoredColliders.Add(otherCollider);

            // Esperar el tiempo configurado
            yield return new WaitForSeconds(ignoreCollisionDuration);

            // Restaurar colisiones (si ambos colliders siguen existiendo)
            if (otherCollider != null && myCollider != null)
            {
                Physics.IgnoreCollision(otherCollider, myCollider, false);
                currentlyIgnoredColliders.Remove(otherCollider);
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using BridgeItTogether.Gameplay.Abstractions;
using BridgeItTogether.Gameplay.SafeZones;

namespace BridgeItTogether.Gameplay.AutoControllers
{
    [DisallowMultipleComponent]
    public class AutoController : MonoBehaviour
    {
        // ==== Movimiento ====
        [Header("Movimiento")]
        [SerializeField] private float velocidadBase = 5f;
        public Vector3 direccionInicial = Vector3.right;

        // ==== Tags (informativos) ====
        [Header("Tags")]
        [SerializeField] private bool asegurarTagVehiculo = true;
        [SerializeField] private string nombreTagVehiculo = "Vehicle";

        // ==== Lanzamiento de IHitable (Parábola Física) ====
        [Header("Lanzamiento IHitable (Parábola Física)")]
        [SerializeField] private string safeZoneTag = "SafeZone";
        [SerializeField, Range(10f, 80f)] private float launchAngleDeg = 45f;
        [SerializeField, Min(0.1f)] private float launchSpeed = 12f;
        [SerializeField, Min(0.1f)] private float launchGravity = 9.81f;
        [SerializeField] private bool kinematicDuringLaunch = true;
        [SerializeField] private float minLaunchDistance = 0.05f;
        [SerializeField] private float ignoreCollisionDuration = 0.5f; // Tiempo para re-habilitar colisiones después del impacto con IHitable

        // Estado
        private Rigidbody rb;
        private bool isInitialized;
        private bool isPaused;
        private Vector3 direccionMovimiento;
        private readonly Dictionary<Transform, Coroutine> activeLaunches = new();
        private readonly HashSet<Collider> currentlyIgnoredColliders = new HashSet<Collider>();

        private void Awake()
        {
            direccionMovimiento = direccionInicial.sqrMagnitude > 0.0001f ? direccionInicial.normalized : Vector3.right;
        }

        public void Initialize(Vector3 direction)
        {
            SetDirection(direction);

            if (asegurarTagVehiculo)
            {
                try
                {
                    if (!string.IsNullOrEmpty(nombreTagVehiculo) && !CompareTag(nombreTagVehiculo))
                        tag = nombreTagVehiculo;
                }
                catch (UnityException)
                {
                    Debug.LogWarning($"[AutoController] Tag '{nombreTagVehiculo}' no existe. Agrega el Tag en Project Settings.", this);
                }
            }

            rb = GetComponent<Rigidbody>() ?? gameObject.AddComponent<Rigidbody>();
#if UNITY_6000_0_OR_NEWER
            rb.linearVelocity = Vector3.zero;
#else
            rb.velocity = Vector3.zero;
#endif
            rb.angularVelocity = Vector3.zero;

            AlinearRotacionConDireccion();
            isInitialized = true;
            isPaused = false;
        }

        protected virtual void FixedUpdate()
        {
            if (!isInitialized || isPaused) return;

            if (rb != null && velocidadBase > 0f)
            {
                Vector3 dir = direccionMovimiento.sqrMagnitude > 0.0001f ? direccionMovimiento.normalized : Vector3.right;
                rb.MovePosition(rb.position + dir * velocidadBase * Time.fixedDeltaTime);
            }
        }

        public void SetSpeed(float speed) => velocidadBase = Mathf.Max(0f, speed);
        public float GetSpeed() => velocidadBase;

        public void SetDirection(Vector3 direction)
        {
            if (direction.sqrMagnitude > 0.0001f)
                direccionMovimiento = direction.normalized;
            AlinearRotacionConDireccion();
        }

        public void Pause()
        {
            isPaused = true;
            if (rb != null)
            {
#if UNITY_6000_0_OR_NEWER
                rb.linearVelocity = new Vector3(0f, rb.linearVelocity.y, 0f);
#else
                rb.velocity = new Vector3(0f, rb.velocity.y, 0f);
#endif
                rb.angularVelocity = Vector3.zero;
            }
        }

        public void Resume()
        {
            isPaused = false;
            AlinearRotacionConDireccion();
        }

        private void AlinearRotacionConDireccion()
        {
            Vector3 look = new Vector3(direccionMovimiento.x, 0f, direccionMovimiento.z);
            if (look.sqrMagnitude > 0.0001f)
                transform.rotation = Quaternion.LookRotation(look, Vector3.up);
        }

        // ===================== IHitable: colisión y lanzamiento =====================
        private void OnCollisionEnter(Collision collision)
        {
            if (!isInitialized) return;

            // Solo procesar colisiones con objetos IHitable (players, etc.)
            var hitable = collision.collider.GetComponentInParent<IHitable>();
            if (hitable == null)
            {
                // No es IHitable: dejar que la física actúe normalmente (suelo, puente, etc.)
                // Solo procesar cuadrantes si aplica
                TryHandleQuadrantCollision(collision.collider);
                return;
            }

            // Es IHitable: ignorar colisiones temporalmente para evitar bugs de colisión repetida
            StartCoroutine(TemporarilyIgnoreCollision(collision.collider));

            // Resto de comportamiento normal para IHitable
            if (TryHandleQuadrantCollision(collision.collider)) return;
            TryLaunchHitable(collision.collider);
        }

        private void OnTriggerEnter(Collider other)
        {
            if (!isInitialized) return;

            if (TryHandleQuadrantCollision(other)) return;
            TryLaunchHitable(other);
        }

        // csharp
        private bool TryHandleQuadrantCollision(Collider col)
        {
            if (col == null) return false;

            var quadrantInst = col.GetComponentInParent<BridgeQuadrantInstance>();
            if (quadrantInst != null && quadrantInst.quadrantSO != null)
            {
                var so = quadrantInst.quadrantSO;
                var layers = so.requiredLayers;

                bool shouldDestroy = false;

                if (layers != null && layers.Length >= 1)
                {
                    bool layer0Done = layers[0].isCompleted;
                    // consider layer2 as the "top" layer; if it doesn't exist treat as not completed
                    bool layer2Done = (layers.Length > 2) ? layers[2].isCompleted : false;

                    // Destroy when base (layer0) is present and the top layer is NOT present.
                    // This covers both: layer1 missing (layer0 built) and layer1 present but layer2 missing.
                    shouldDestroy = layer0Done && !layer2Done;
                }
                else
                {
                    // Fallback: require first layer completed and last layer not completed
                    if (layers != null && layers.Length > 0)
                    {
                        bool firstDone = layers[0].isCompleted;
                        bool lastDone = layers[layers.Length - 1].isCompleted;
                        shouldDestroy = firstDone && !lastDone;
                    }
                }

                if (shouldDestroy)
                {
                    so.ForceDestroyQuadrant();
                    Debug.Log($"[AutoController] Forced destroy quadrant on '{quadrantInst.name}' due to vehicle collision.");
                    return true;
                }

                // If conditions not met (e.g. top layer already completed), do not destroy and allow normal pass-through
                return false;
            }

            return false;
        }


        private void TryLaunchHitable(Collider col)
        {
            if (col == null) return;

            var hitable = col.GetComponent<IHitable>();
            if (hitable == null) return;

            var targetT = (hitable as Component)?.transform;
            if (targetT == null) return;

            if (IsObjectBeingHeld(targetT))
            {
                var holder = FindPlayerHoldingObject(targetT);
                if (holder != null)
                {
                    TryLaunchHitable(holder.GetComponent<Collider>());
                }
                return;
            }

            if (targetT != transform && targetT.IsChildOf(transform))
                targetT.SetParent(null, true);

            if (activeLaunches.ContainsKey(targetT)) return;

            if (!TryGetRandomPointInNearestSafeZone(targetT.position, out var destino)) return;

            hitable.OnLaunched(destino);

            var routine = StartCoroutine(LaunchRoutine(targetT, destino));
            activeLaunches[targetT] = routine;
        }

        private bool IsObjectBeingHeld(Transform obj)
        {
            var holders = FindObjectsOfType<PlayerObjectHolder>();
            foreach (var holder in holders)
            {
                if (holder.HasObjectInHand() && holder.GetHeldObject() == obj.gameObject)
                    return true;
            }
            return false;
        }

        private PlayerObjectHolder FindPlayerHoldingObject(Transform obj)
        {
            var holders = FindObjectsOfType<PlayerObjectHolder>();
            foreach (var holder in holders)
            {
                if (holder.HasObjectInHand() && holder.GetHeldObject() == obj.gameObject)
                    return holder;
            }
            return null;
        }

        private IEnumerator LaunchRoutine(Transform target, Vector3 destino)
        {
            if (target == null) yield break;
            if (target.IsChildOf(transform))
                target.SetParent(null, true);

            Vector3 start = target.position;
            Vector3 end = destino;

            // Calcular distancia horizontal y diferencia de altura
            Vector3 horizontalDisplacement = new Vector3(end.x - start.x, 0f, end.z - start.z);
            float horizontalDistance = horizontalDisplacement.magnitude;

            if (horizontalDistance < minLaunchDistance)
            {
                activeLaunches.Remove(target);
                yield break;
            }

            Vector3 horizontalDir = horizontalDisplacement / horizontalDistance;
            float heightDifference = end.y - start.y;

            // Calcular velocidad inicial necesaria para llegar EXACTAMENTE al destino
            // Fórmula balística: v = sqrt(g * d^2 / (2 * cos^2(θ) * (d * tan(θ) - h)))
            float g = Mathf.Max(0.01f, launchGravity);
            float angleRad = launchAngleDeg * Mathf.Deg2Rad;
            float tanAngle = Mathf.Tan(angleRad);
            float cosAngle = Mathf.Cos(angleRad);

            float denominator = 2f * cosAngle * cosAngle * (horizontalDistance * tanAngle - heightDifference);

            if (denominator <= 0f)
            {
                // No hay solución física con este ángulo, usar velocidad fija como fallback
                Debug.LogWarning($"[AutoController] No se puede calcular trayectoria exacta con ángulo {launchAngleDeg}°. Usando fallback.");
                activeLaunches.Remove(target);
                yield break;
            }

            float velocitySquared = (g * horizontalDistance * horizontalDistance) / denominator;
            float velocity = Mathf.Sqrt(velocitySquared);

            // Calcular tiempo de vuelo
            float totalTime = horizontalDistance / (velocity * cosAngle);

            // Detectar si tiene CharacterController (Players) o Rigidbody (Materiales, objetos)
            CharacterController charController = target.GetComponent<CharacterController>();
            Rigidbody trb = target.GetComponent<Rigidbody>();

            bool hasCharController = charController != null;
            bool hasRigidbody = trb != null;

            bool prevCharControllerEnabled = false;
            bool prevRigidbodyKinematic = false;

            // Deshabilitar CharacterController durante lanzamiento (Players)
            if (hasCharController)
            {
                prevCharControllerEnabled = charController.enabled;
                charController.enabled = false;
            }

            // Hacer kinematic el Rigidbody durante lanzamiento (Materiales/objetos con física)
            if (hasRigidbody && kinematicDuringLaunch)
            {
                prevRigidbodyKinematic = trb.isKinematic;
#if UNITY_6000_0_OR_NEWER
                trb.linearVelocity = Vector3.zero;
#else
                trb.velocity = Vector3.zero;
#endif
                trb.angularVelocity = Vector3.zero;
                trb.isKinematic = true;
            }

            // Ejecutar parábola balística exacta
            float t = 0f;
            Vector3 lastPosition = start;

            while (t < totalTime && target != null)
            {
                t += Time.deltaTime;
                float ct = Mathf.Clamp(t, 0f, totalTime);

                // Posición horizontal (movimiento uniforme)
                float horizontalProgress = velocity * cosAngle * ct;

                // Posición vertical (movimiento parabólico)
                float verticalProgress = velocity * Mathf.Sin(angleRad) * ct - 0.5f * g * ct * ct;

                lastPosition = target.position;
                Vector3 newPosition = start + horizontalDir * horizontalProgress;
                newPosition.y = start.y + verticalProgress;

                target.position = newPosition;

                yield return null;
            }

            // Calcular velocidad final de la trayectoria para que continúe cayendo naturalmente
            Vector3 finalVelocity = Vector3.zero;
            if (target != null && Time.deltaTime > 0f)
            {
                finalVelocity = (target.position - lastPosition) / Time.deltaTime;
            }

            // Restaurar CharacterController (caerá por gravedad natural)
            if (hasCharController && charController != null)
            {
                charController.enabled = prevCharControllerEnabled;
            }

            // Restaurar Rigidbody y aplicar velocidad final para continuar la trayectoria
            if (hasRigidbody && trb != null)
            {
                if (kinematicDuringLaunch)
                {
                    trb.isKinematic = prevRigidbodyKinematic;
                }

                // Aplicar velocidad solo si no es kinematic
                if (!trb.isKinematic)
                {
#if UNITY_6000_0_OR_NEWER
                    trb.linearVelocity = finalVelocity;
#else
                    trb.velocity = finalVelocity;
#endif
                }
            }


            if (target != null)
                activeLaunches.Remove(target);
        }

        private bool TryGetRandomPointInNearestSafeZone(Vector3 from, out Vector3 point)
        {
            point = default;
            GameObject[] zones = GameObject.FindGameObjectsWithTag(safeZoneTag);
            if (zones == null || zones.Length == 0) return false;

            SafeZoneArea bestArea = null;
            Transform fallback = null;
            float bestDist = float.MaxValue;

            for (int i = 0; i < zones.Length; i++)
            {
                var go = zones[i];
                if (go == null) continue;

                var area = go.GetComponent<SafeZoneArea>();
                var t = go.transform;
                float d = (t.position - from).sqrMagnitude;

                if (area != null)
                {
                    if (d < bestDist)
                    {
                        bestDist = d;
                        bestArea = area;
                        fallback = t;
                    }
                }
                else
                {
                    if (d < bestDist)
                    {
                        bestDist = d;
                        fallback = t;
                    }
                }
            }

            if (bestArea != null)
            {
                point = bestArea.GetRandomPointInside();
                return true;
            }

            if (fallback != null)
            {
                point = fallback.position;
                return true;
            }

            return false;
        }

        /// <summary>
        /// Ignora temporalmente las colisiones con el collider especificado (solo IHitable) y luego las restaura.
        /// Esto evita bugs de colisión repetida mientras permite que el auto vuelva a chocar más adelante.
        /// </summary>
        private IEnumerator TemporarilyIgnoreCollision(Collider otherCollider)
        {
            if (otherCollider == null) yield break;

            var myCollider = GetComponent<Collider>();
            if (myCollider == null) yield break;

            // Si ya estamos ignorando este collider, no duplicar la coroutine
            if (currentlyIgnoredColliders.Contains(otherCollider)) yield break;

            // Ignorar colisiones
            Physics.IgnoreCollision(otherCollider, myCollider, true);
            currentlyIgnoredColliders.Add(otherCollider);

            // Esperar el tiempo configurado
            yield return new WaitForSeconds(ignoreCollisionDuration);

            // Restaurar colisiones (si ambos colliders siguen existiendo)
            if (otherCollider != null && myCollider != null)
            {
                Physics.IgnoreCollision(otherCollider, myCollider, false);
                currentlyIgnoredColliders.Remove(otherCollider);
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Objeto genérico tipo 3 que permite al jugador obtener un material tipo 3 (superficie)
/// al mantener presionado el botón de interacción durante 1 segundo.
/// En la era prehistórica, este material es un adoquín.
/// </summary>
public class GenericObject3 : MonoBehaviour, IInteractable, IHoldInteractable
{    
    [Header("Configuración de objeto")]
    [SerializeField] private MaterialPrefabSO materialPrefabsSO; // Referencia al SO con los prefabs
    [SerializeField] private BridgeQuadrantSO.EraType era = BridgeQuadrantSO.EraType.Prehistoric;
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;
    [SerializeField] private GameObject shadow;

    [Header("Configuración de generación")]
    [SerializeField] private float tiempoPresionado = 1.0f; // Tiempo que hay que mantener presionado
    [SerializeField] private float tiempoRecarga = 2.0f; // Tiempo antes de poder generar otro material

    // Variables para controlar el estado
    private bool enRecarga = false;
    private bool enProceso = false;
    private float tiempoActual = 0f;
    private GameObject jugadorInteractuando = null;

    // Propiedad requerida por la interfaz IInteractable
    public InteractPriority InteractPriority => interactPriority;    

    private void Start()
    {
        // Verificar que tengamos las referencias necesarias
        if (materialPrefabsSO == null)
        {
            Debug.LogError("No se ha asignado el MaterialPrefabSO en " + gameObject.name);
        }

        shadow.SetActive(false);
    }

    private void Update()
    {
        // Si estamos en proceso de generar el material
        if (enProceso && jugadorInteractuando != null)
        {
            tiempoActual += Time.deltaTime;

            // Si se completa el tiempo requerido
            if (tiempoActual >= tiempoPresionado)
            {
                EntregarMaterial();
                ResetearProceso();
                StartCoroutine(Recargar());
            }

            // Aquí podrías añadir efectos visuales o sonidos que indiquen el progreso
            // Por ejemplo, una barra de progreso o un efecto de partículas que aumenta
        }
    }

    // Método llamado cuando un jugador interactúa con este objeto
    public void Interact(GameObject interactor)
    {
        if (enRecarga)
        {
            Debug.Log("Objeto en recarga, espera un momento.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = interactor.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            // Iniciamos el proceso de mantener presionado
            if (!enProceso)
            {
                IniciarProceso(interactor);
                Debug.Log("Mantén presionado para obtener el material tipo 3 (superficie).");
            }
        }
        else
        {
            Debug.Log("El interactor no tiene el componente PlayerObjectHolder.");
        }
    }

    // Método llamado cuando el jugador suelta el botón de interacción
    public void DetenerInteraccion()
    {
        if (enProceso)
        {
            ResetearProceso();
            Debug.Log("Proceso cancelado. Debes mantener presionado el botón.");
        }
    }

    private void IniciarProceso(GameObject interactor)
    {
        enProceso = true;
        tiempoActual = 0f;
        jugadorInteractuando = interactor;

        // Aquí podrías iniciar efectos visuales o sonidos
    }

    private void ResetearProceso()
    {
        enProceso = false;
        tiempoActual = 0f;
        jugadorInteractuando = null;

        // Detener efectos visuales o sonidos
    }    

    private void EntregarMaterial()
    {
        if (materialPrefabsSO == null || jugadorInteractuando == null)
        {
            Debug.LogError("Falta MaterialPrefabSO o jugador para entregar material.");
            return;
        }

        // Obtener el prefab del material tipo 3 para la era actual
        GameObject materialPrefab = materialPrefabsSO.GetMaterialPrefab(3, era);

        if (materialPrefab == null)
        {
            Debug.LogError($"No se encontró prefab para material tipo 3 de la era {era}.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = jugadorInteractuando.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            if (playerObjectHolder.HasObjectInHand())
            {
                Debug.Log("Jugador ya sostiene un objeto. Intercambiando objetos.");
            }

            // Generar una nueva instancia del material de superficie en la escena
            GameObject nuevoMaterial = Instantiate(materialPrefab, transform.position + Vector3.up * 0.5f, transform.rotation);

            // Configurar el material generado
            ConfigurarMaterialGenerado(nuevoMaterial);

            // Lógica para asignar el UIIndex al nuevo material, igual que GenericObject1
            UIIndexSetter sourceIndexSetter = GetComponent<UIIndexSetter>();
            int indexToAssign = sourceIndexSetter != null ? sourceIndexSetter.UIIndex : -1;

            UIIndexSetter uiIndexSetter = nuevoMaterial.GetComponent<UIIndexSetter>();
            if (uiIndexSetter == null)
            {
                uiIndexSetter = nuevoMaterial.AddComponent<UIIndexSetter>();
            }
            uiIndexSetter.SetUIIndex(indexToAssign);

            // Hacer que el jugador recoja la instancia recién creada
            playerObjectHolder.PickUpExistingInstance(nuevoMaterial);
            Debug.Log("Material tipo 3 (superficie) entregado con éxito.");

            // Opcional: Reproducir sonido o efecto visual
            ProducirEfectos();
        }
    }

    private void ConfigurarMaterialGenerado(GameObject material)
    {
        // Configurar el material generado como material de tipo superficie (nuevo tipo 3) de la era correspondiente
        BridgeMaterialInfo materialInfo = material.GetComponent<BridgeMaterialInfo>();
        if (materialInfo == null)
        {
            materialInfo = material.AddComponent<BridgeMaterialInfo>();
        }

        materialInfo.layerIndex = 2; // Tipo superficie corresponde a la capa superior (índice 2)
        materialInfo.era = era;
        materialInfo.materialType = BridgeQuadrantSO.MaterialType.Stone; // Superficie usa piedra/adoquín

        material.tag = "BridgeLayer2";

        Debug.Log($"Material superficie generado configurado: Era {era}, Capa 2, Tipo Stone");
    }

    private IEnumerator Recargar()
    {
        enRecarga = true;

        // TODO: Aquí puedes añadir una animación o cambio visual que indique la recarga

        yield return new WaitForSeconds(tiempoRecarga);

        enRecarga = false;
    }

    private void ProducirEfectos()
    {
        // TODO: Reproducir efectos visuales o sonidos
    }
}

